16	var (
17		migrateCmd = &cobra.Command{
18			Use:   "migrate [sub]",
19			Short: "migration db auth",
20			Run: func(cmd *cobra.Command, args []string) {
21				if len(args) == 0 {
22					zap.L().Fatal("Wrong arrgument enter up or down")
23				}
24				switch args[0] {
25				case "up":
26					upCmd.Run(cmd, args)
27				case "down":
28					downCmd.Run(cmd, args)
29				}
30			},
31		}
32		upCmd = &cobra.Command{
33			Use:   "up [no options!]",
34			Short: "migrate up",
35			Run: func(cmd *cobra.Command, args []string) {
36				var err error
37				defer func() {
38					if err != nil {
39						zap.L().Fatal("", zap.Error(err))
40					}
41				}()
42	
43				db, err := migrationInit()
44				if err != nil {
45					return
46				}
47				defer db.Close()
48				up(db)
49			},
50		}
51		downCmd = &cobra.Command{
52			Use:   "down [no options!]",
53			Short: "migrate down",
54			Run: func(cmd *cobra.Command, args []string) {
55				var err error
56				defer func() {
57					if err != nil {
58						zap.L().Fatal("", zap.Error(err))
59					}
60				}()
61	
62				db, err := migrationInit()
63				if err != nil {
64					return
65				}
66				defer db.Close()
67				down(db)
68			},
69		}
70		migrations = &migrate.MemoryMigrationSource{
71			Migrations: []*migrate.Migration{
72				&migrate.Migration{
73					Id: "1",
74					Up: []string{
75						`CREATE TABLE users(
76						uid           uuid   PRIMARY KEY  NOT NULL,
77						email          text    NOT NULL,
78						password        text   NOT NULL,
79						first_name      text,
80						last_name 		text,
81						created_at  TIMESTAMP
82					 );`,
83						`CREATE TABLE sessions(
84						session_hash  text   PRIMARY KEY,
85						user_id           uuid references users(uid),
86						ip_address      text not null,
87						user_agent text default '',
88						created_at  TIMESTAMP
89					 );`,
90						`CREATE EXTENSION pgcrypto;`},
91					Down: []string{
92						"DROP TABLE sessions;",
93						"DROP TABLE users;",
94						"DROP EXTENSION pgcrypto;"},
95				},
96			},
97		}
98	)
99	
100	func init() {
101		RootCmd.AddCommand(migrateCmd)
102	}
103	
104	func migrationInit() (*sql.DB, error) {
105		log, err := zap.NewProduction()
106		if err != nil {
107			log.Fatal("", zap.Error(err))
108		}
109	
110		cfg, err := config.Read()
111		if err != nil {
112			log.Warn("", zap.Error(errors.New("wrong cfg")))
113			return nil, err
114		}
115		args := fmt.Sprintf(
116			"REDACTED",
117			cfg.DB.SSL,
118			cfg.DB.Host,
119			cfg.DB.Port,
120			cfg.DB.User,
121			cfg.DB.Password,
122			cfg.DB.DatabaseName,
123		)
124		postDB, err := sql.Open("postgres", args)
125		if err != nil {
126			zap.L().Warn("", zap.Error(err))
127			return nil, err
128		}
129		return postDB, nil
130	}
131	
132	func up(postDB *sql.DB) {
133		affected, err := migrate.Exec(postDB, "postgres", migrations, migrate.Up)
134		if err != nil {
135			zap.L().Warn("", zap.Error(err))
136			return
137		}
138		zap.L().Info("", zap.Int("up migration applied:", affected))
139	}
140	func down(postDB *sql.DB) {
141		affected, err := migrate.ExecMax(postDB, "postgres", migrations, migrate.Down, 1)
142		if err != nil {
143			zap.L().Warn("", zap.Error(err))
144			return
145		}
146		zap.L().Info("", zap.Int("down migration applied:", affected))
147	}
